std::size_t find_tag_end(std::string_view s, std::size_t start) {
    char quote = 0;
    for (std::size_t i = start; i < s.size(); ++i) {
        const char c = s[i];
        if (quote) { if (c == quote) quote = 0; }
        else if (c == '"' || c == '\'') quote = c;
        else if (c == '>') return i;
