std::expected<Coverage, ParseError> parse_cobertura(std::string_view xml, bool fold_case) {
    Coverage cov;
    std::size_t pos = 0, classes = 0, lines = 0;
    if (xml.starts_with("\xEF\xBB\xBF")) pos = 3;

    while (pos < xml.size()) {
        // пропустить комментарии
        if (xml.substr(pos, 4) == "<!--") { ... }
        const auto open = xml.find("<class", pos);
        if (open == npos) break;
        if (!tag_starts(xml, open, "<class")) { pos = open + 1; continue; }
        const auto tag_end = find_tag_end(xml, open);
        if (tag_end == npos) return unexpected(error(malformed, open, "unterminated <class>"));
        const auto raw_name = attr(xml.substr(open, tag_end - open + 1), "filename");
        if (!raw_name) return unexpected(error(malformed, open, "<class> without filename"));
        const std::string path = decode_entities(*raw_name);
        const auto close = xml.find("</class>", tag_end);
        if (close == npos) return unexpected(error(malformed, tag_end, "unterminated class body"));
        // внутри [tag_end+1; close) искать <line ...>
        std::size_t p = tag_end + 1;
        for (;;) {
            const auto l = xml.find("<line", p);
            if (l == npos || l >= close) break;
            if (!tag_starts(xml, l, "<line")) { p = l + 1; continue; }
            const auto le = find_tag_end(xml, l);
            if (le == npos || le > close) return unexpected(error(malformed, l, "unterminated <line>"));
            const auto tag = xml.substr(l, le - l + 1);
            const auto num = attr(tag, "number");
            const auto hits = attr(tag, "hits");
            if (!num || !hits) return unexpected(error(malformed, l, "<line> without number/hits"));
            std::uint64_t n = 0, h = 0;
            if (!parse_u64(*num, n) || !parse_u64(*hits, h) || n == 0 || n > INT_MAX)
                return unexpected(error(malformed, l, "invalid line number/hits"));
            const auto key = normalize_key(path, fold_case);
            auto& fc = cov.files[key];
            if (fc.display_path.empty()) fc.display_path = path;
            auto& slot = fc.hits[static_cast<int>(n)];
            slot = std::max(slot, h);
            ++lines;
            p = le + 1;
        }
        ++classes;
        pos = close + 8;
    }
    if (classes == 0) return unexpected(error(no_classes, 0, "no <class> in report"));
    if (lines == 0) return unexpected(error(no_lines, 0, "no <line> in report"));
    return cov;
}
