        while (i < tag.size() && is_xml_space(tag[i])) ++i;
        if (i >= tag.size() || tag[i] != '=') { /* attribute without value */ continue; }
        ++i;
        while (i < tag.size() && is_xml_space(tag[i])) ++i;
        if (i >= tag.size() || (tag[i] != '"' && tag[i] != '\'')) return std::nullopt; // or skip
