        const std::size_t vs = i;
        while (i < tag.size() && tag[i] != q) ++i;
        if (i >= tag.size()) return std::nullopt;
        if (aname == name) return tag.substr(vs, i - vs);
        ++i;
    }
    return std::nullopt;
}
