    char quote = '\0';
    for (std::size_t i = start; i < s.size(); ++i) {
        const char c = s[i];
        if (quote != '\0') {
            if (c == quote) quote = '\0';
        } else if (c == '"' || c == '\'') {
            quote = c;
        } else if (c == '>') {
            return i;
        }
    }
    return std::string_view::npos;
}

// порядок атрибутов не важен; кавычки одинарные/двойные
std::optional<std::string_view> find_attr(std::string_view tag, std::string_view name) {
    std::size_t i = 0;
    while (i < tag.size()) {
        while (i < tag.size() && is_xml_space(tag[i])) ++i;
        if (i >= tag.size() || tag[i] == '>' || tag[i] == '/') break;

        const std::size_t ns = i;
        while (i < tag.size() && !is_xml_space(tag[i]) && tag[i] != '=' && tag[i] != '>' && tag[i] != '/') ++i;
        const std::string_view aname = tag.substr(ns, i - ns);

        while (i < tag.size() && is_xml_space(tag[i])) ++i;
        if (i >= tag.size() || tag[i] != '=') continue;
        ++i;
        while (i < tag.size() && is_xml_space(tag[i])) ++i;
        if (i >= tag.size() || (tag[i] != '"' && tag[i] != '\'')) return std::nullopt;

        const char quote = tag[i++];
        const std::size_t vs = i;
        while (i < tag.size() && tag[i] != quote) ++i;
        if (i >= tag.size()) return std::nullopt;

        const std::string_view value = tag.substr(vs, i - vs);
        ++i;
        if (aname == name) return value;
    }
    return std::nullopt;
}

std::string decode_entities(std::string_view raw) {
    std::string out;
    out.reserve(raw.size());
    for (std::size_t i = 0; i < raw.size(); ++i) {
        if (raw[i] != '&') {
            out += raw[i];
        } else if (raw.substr(i, 5) == "&amp;") {
            out += '&';
            i += 4;
        } else if (raw.substr(i, 4) == "&lt;") {
            out += '<';
            i += 3;
        } else if (raw.substr(i, 4) == "&gt;") {
            out += '>';
            i += 3;
        } else if (raw.substr(i, 6) == "&quot;") {
            out += '"';
            i += 5;
        } else if (raw.substr(i, 6) == "&apos;") {
            out += '\'';
            i += 5;
        } else {
            out += raw[i];
        }
    }
    return out;
}

bool parse_u64(std::string_view s, std::uint64_t& out) {
    if (s.empty()) return false;
    const auto [ptr, ec] = std::from_chars(s.data(), s.data() + s.size(), out);
    return ec == std::errc{} && ptr == s.data() + s.size();
}

// \ -> /, схлопнуть //, на Windows lower-case
std::string normalize_key(std::string_view path, bool fold_case) {
    std::string out;
    out.reserve(path.size());
    bool prev_slash = false;
    for (char c : path) {
        if (c == '\\') c = '/';
        if (c == '/' && prev_slash) continue;
        prev_slash = (c == '/');
        if (fold_case && c >= 'A' && c <= 'Z') c = static_cast<char>(c - 'A' + 'a');
        out += c;
    }
    return out;
}

std::string relative_path(std::string_view path, std::string_view source_root) {
    if (source_root.empty()) return std::string(path);
    const std::filesystem::path p{path};
    const std::filesystem::path root{source_root};
    const std::string rel = p.lexically_relative(root).generic_string();
    if (rel.empty() || rel.starts_with("..")) return std::string(path);
    return rel;
}

ParseError make_error(ParseReason reason, std::size_t offset, std::string what) {
    return ParseError{reason, offset, std::move(what)};
}

} // namespace
```

