Важно: `xml.find("<class", pos)` может найти `<class` **внутри комментария**. Если хочешь поддержку комментариев — перед `find` обрабатывай `<!-- ... -->`; иначе явно запиши в комментарии парсера, что комментарии не поддерживаются (для текущего отчёта их нет).

### `summarize`

```cpp
Summary summarize(const Coverage& cov, std::string_view source_root) {
    Summary out{};
    for (const auto& [key, fc] : cov.files) {
        const std::string display = relative_path(fc.display_path, source_root);
        int covered = 0;
        std::vector<int> missing;
        for (const auto& [line, h] : fc.hits) {
            if (h > 0) ++covered;
            else missing.push_back(line);
        }
        const int valid = static_cast<int>(fc.hits.size());
        out.files.push_back(FileStat{display, covered, valid});
        if (!missing.empty()) out.uncovered.push_back(Uncovered{display, std::move(missing)});
        out.covered += covered;
        out.valid += valid;
    }
    return out;
}
