std::vector<std::string> missing_expected(const Coverage& cov,
                                          std::span<const std::string> expected,
                                          bool fold_case) {
    std::vector<std::string> missing;
    for (const auto& e : expected) {
        const auto it = cov.files.find(normalize_key(e, fold_case));
        if (it == cov.files.end() || it->second.hits.empty()) missing.push_back(e);
