156: std::expected<Coverage, ParseError> parse_cobertura(std::string_view xml, bool fold_case) {
157:     Coverage cov;
158:     constexpr std::string_view kClassClose = "</class>";
159:     std::size_t pos = 0;
160:     std::size_t classes = 0;
161:     std::size_t lines = 0;
162:     if (xml.starts_with("\xEF\xBB\xBF")) pos = 3;
163: 
164:     while (pos < xml.size()) {
165:         std::size_t open = xml.find("<class", pos); 
166:         if (open == std::string::npos) break;
167:         // проверка что это именно <class...> - сам тэг просто class, после - пробел. иначе - ищем далее
168:         if (!tag_starts(xml, open, "<class")){ 
169:         pos = open + 1;
170:         continue;
171:         }
172:         // закрывающий тег есть? если его нет, этот формат этого файла в этом моменте неверный
173:         std::size_t tag_end = find_tag_end(xml, open);
174:         if (tag_end == std::string::npos) return std::unexpected(malformed); 
175:         // вырезать данные м-у < и >
176:         std::string tag = xml.substr(open, tag_end - open + 1)
177:         // внутри тега class должен быть атрибут filename. если его нет, этот формат этого файла в этом моменте неверный
178:         auto raw = find_attr(tag, "filename");
179:         if (raw == std::nullopt) return std::unexpected(malformed);
180:         // убрать спецсимволы из пути 
181:         std::path = decode_entities(*raw);
182:         // закрывающий тэг. если его нет, этот формат этого файла в этом моменте неверный
183:         std::size_t close = xml.find("</class>", tag_end);
184:         if (close == std::npos) return std::unexpected(malformed);
185:         // строки в <class>
186:         std::size_t p = tag_end + 1; 
187:         // пространство м-у концом <class ...> и </class>, ожидаем line-s внутри
188: while (p < close){
189: std::size_t l = xml.find("<line", p);
190: // если не нашли <line или вышли за границы <class ...> и </class>, выходим
191: if (l == std::npos || l > close) break;
192: // должно быть именно <line ...>, не <lines ...>
193: if (!tag_starts(xml, l, "<line")) {
194: // чтобы не застряться, сдвигаемся на 1 и продолжаем поиск
195: p = l + 1;
196: continue;
197: }
198: // конец <line ...; если его нет или он за </class> - это момент формата в данном файле некорректен
199: std::size_t le = find_tag_end(xml, l);
200: if (le == std::npos || le > close) return std::unexpected(malformed);
201: // внутренность <line ... />
202: std::string ltag = xml.substr(l, le - l + 1);
203: 
204: // нахождение тегов number и hits внутри <line ... />. если их нет - "плохой формат" в этом файле
205: auto raw_n = find_attr(ltag, "number"); 
206: auto raw_h = find_attr(ltag, "hits");
207: if (raw_n == std::npos || raw_h == std::npos) return std::unexpected(malformed);
208: // распознавание чисел после тегов number и hits
209: std::uint64_t n = 0, h = 0;
210: // если они распознаны некорректно или n нереальное для строки - "ошибка формата"
211: if (parse_u64(raw_n, n) && parse_u64(raw_h, h)) return std::unexpected(malformed);
212: if (n =< 0 || n > INT_MAX) return std::unexpected(malformed);
213: // fold_case == true -> приводим к нижнему регистру, тк он неважен; false -> оставляем строку как есть
214: // и нормализовать слеши
215: std::string key = normalize_key(path, fold_case);
216: 
217: // покрытие конкретного файла
218: FileCoverage fc = cov.files[key];
219: // если у данного файла нет пути до него - добавляем
220: if(is_empty(fc.display_path)) fc.display_path = path;
221: fc.hits[(int)n] = std::max(fc.hits[(int)n], h);
222: // +1 корректная строка
223: ++lines; 
224: // переходим за её границу, чтобы не застрять на ней
225: p = le + 1;
226: }
227: // если попали сюда, то прошли все <line ... внутри <class>...</class>
228: ++classes;
229: // close стоит на начале </class>, сдвигаемся на kClassClose.size() - за </class> 
230: pos = close + kClassClose.size();
231:     }
232: 
233:     if (classes == 0) return std::unexpected(make_error(ParseReason::no_classes, 0, "no <class> in report"));
234:     if (lines == 0)    return std::unexpected(make_error(ParseReason::no_lines, 0, "no <line> in report"));
235:     return cov;
236: }
