239: Summary summarize(const Coverage& cov, std::string_view source_root) {
240:     Summary out{};
241:     for (const auto& [key, fc] : cov.files) {
242:         // относит. путь, подсчёт - покрытые и какие именно непокрытые
243:         const std::string display = relative_path(fc.display_path, source_root);
244:         int covered = 0;
245:         std::vector<int> missing;
246:         for (const auto& [line, h] : fc.hits) {
247:             if (h > 0) ++covered;
248:             else missing.push_back(line);
249:         }
250:         // сколько всего инструментированных строк по данному файлу
251:         const int valid = static_cast<int>(fc.hits.size());
252:         // добавляем в итоговый Summary статистику по текущему файлу
253:         out.files.push_back(FileStat{display, covered, valid});
254:         // есть непокрытые строки? в uncovered curr-файла перемещаем missing, тк сам missing здесь более не нужен
255:         if (!missing.empty()) out.uncovered.push_back(Uncovered{display, std::move(missing)});
256:         // вклад данного файла (всего и покрытые) в итоговую статистику
257:         out.covered += covered;
258:         out.valid += valid;
259:     }
260:     return out;
261: }
