274:     for (const auto& f : s.files) width = std::max(width, f.path.size());
275: 
276:     // шапка и все записи по файлам. и итоговая запись с "всего" и "покрыто" по всему проекту
277:     std::string out = "coverage union (line-based, Cobertura)\n";
278:     for (const auto& f : s.files) out += format_line(f.path, f.covered, f.valid, width);
279:     out += format_line("TOTAL", s.covered, s.valid, width);
