178: // parse_cobertura — алгоритм
179: std::expected<Coverage, ParseError> parse_cobertura(std::string_view xml, bool fold_case) {
180:     Coverage cov;
181:     constexpr std::string_view kClassClose = "</class>";
182:     std::size_t pos = 0;
183:     std::size_t classes = 0;
184:     std::size_t lines = 0;
185:     if (xml.starts_with("\xEF\xBB\xBF"))
186:         pos = 3;
187: 
188:     while (pos < xml.size()) {
189:         std::size_t open = xml.find("<class", pos);
190:         if (open == std::string_view::npos)
191:             break;
192:         // проверка что это именно <class...> - сам тэг просто class, после - пробел. иначе - ищем далее
193:         if (!tag_starts(xml, open, "<class")) {
194:             pos = open + 1;
195:             continue;
196:         }
197:         // конц.часть(>) открывающего тега есть? если его нет - "плохой формат"
198:         std::size_t tag_end = find_tag_end(xml, open);
199:         if (tag_end == std::string::npos)
200:             return std::unexpected(make_error(ParseReason::malformed, off, "no closing angle bracket in class tag"));
201:         // вырезать данные м-у < и >
202:         std::string_view tag = xml.substr(open, tag_end - open + 1);
203:         // внутри тега class должен быть атрибут filename. если его нет, этот формат этого файла в этом моменте неверный
204:         auto raw = find_attr(tag, "filename");
205:         if (raw == std::nullopt)
206:             return std::unexpected(make_error(ParseReason::malformed, off, "no filename attribute inside class tag"));
207:         // убрать спецсимволы из пути
208:         std::string path = decode_entities(*raw);
209:         // закрывающий тэг. если его нет, этот формат этого файла в этом моменте неверный
210:         std::size_t close = xml.find("</class>", tag_end);
211:         if (close == std::string::npos)
212:             return std::unexpected(make_error(ParseReason::malformed, off, "no pair </class> after <class>"));
213:         // строки в <class>
214:         std::size_t p = tag_end + 1;
215:         // пространство м-у концом <class ...> и </class>, ожидаем line-s внутри
216:         while (p < close) {
217:             std::size_t l = xml.find("<line", p);
218:             // если не нашли <line или вышли за границы <class ...> и </class>, выходим
219:             if (l == std::string::npos || l > close)
220:                 break;
221:             // должно быть именно <line ...>, не <lines ...>
222:             if (!tag_starts(xml, l, "<line")) {
223:                 // чтобы не застряться, сдвигаемся на 1 и продолжаем поиск
224:                 p = l + 1;
225:                 continue;
226:             }
227:             // конец <line ...; если его нет или он за </class> - это момент формата в данном файле некорректен
228:             std::size_t le = find_tag_end(xml, l);
229:             if (le == std::string::npos || le > close)
230:                 return std::unexpected(make_error(ParseReason::malformed, off, "no /> after <line or /> is too far"));
231:             // внутренность <line ... />
232:             std::string_view ltag = xml.substr(l, le - l + 1);
233: 
234:             // нахождение тегов number и hits внутри <line ... />. если их нет - "плохой формат" в этом файле
235:             auto raw_n = find_attr(ltag, "number");
236:             if (!raw_n)
237:                 return std::unexpected(make_error(ParseReason::malformed, off, "no number attribute inside line tag"));
238:             auto raw_h = find_attr(ltag, "hits");
239:             if (!raw_h)
240:                 return std::unexpected(make_error(ParseReason::malformed, off, "no hits attribute inside line tag"));
241: 
242:             // распознавание чисел после тегов number и hits
243:             std::uint64_t n = 0, h = 0;
244:             // если они распознаны некорректно или n нереальное для строки - "ошибка формата"
245:             if (!parse_u64(*raw_n, n) || !parse_u64(*raw_h, h))
246:                 return std::unexpected(malformed);
247:             if (n == 0 || n > static_cast<std::uint64_t>(std::numeric_limits<int>::max()))
248:                 return std::unexpected(
249:                     make_error(ParseReason::malformed, off, "line number is incorrect: non-positive or more than int"));
250:             // fold_case == true -> приводим к нижнему регистру, тк он неважен; false -> оставляем строку как есть
251:             // и нормализовать слеши
252:             std::string key = normalize_key(path, fold_case);
253: 
254:             // покрытие конкретного файла
255:             FileCoverage& fc = cov.files[key];
256:             // если у данного файла нет пути до него - добавляем
257:             if (fc.display_path.empty())
258:                 fc.display_path = path;
259:             fc.hits[static_cast<int>(n)] = std::max(fc.hits[(int)n], h);
260:             // +1 корректная строка
261:             ++lines;
262:             // переходим за её границу, чтобы не застрять на ней
263:             p = le + 1;
264:         }
265:         // если попали сюда, то прошли все <line ... внутри <class>...</class>
266:         ++classes;
267:         // close стоит на начале </class>, сдвигаемся на kClassClose.size() - за </class>
268:         pos = close + kClassClose.size();
269:     }
270: 
271:     if (classes == 0)
272:         return std::unexpected(make_error(ParseReason::no_classes, 0, "no <class> in report"));
273:     if (lines == 0)
274:         return std::unexpected(make_error(ParseReason::no_lines, 0, "no <line> in report"));
275:     return cov;
276: }
