278: // итоговая статистика по проекту
279: Summary summarize(const Coverage& cov, std::string_view source_root) {
280:     Summary out{};
281:     for (const auto& entry : cov.files) {
282:         const auto& fc = entry.second;
283:         // относит. путь, подсчёт - покрытые и какие именно непокрытые
284:         const std::string display = relative_path(fc.display_path, source_root);
285:         int covered = 0;
286:         std::vector<int> missing;
287:         for (const auto& [line, h] : fc.hits) {
288:             if (h > 0)
289:                 ++covered;
290:             else
291:                 missing.push_back(line);
292:         }
293:         // сколько всего инструментированных строк по данному файлу
294:         const int valid = static_cast<int>(fc.hits.size());
295:         // добавляем в итоговый Summary статистику по текущему файлу
296:         out.files.push_back(FileStat{display, covered, valid});
297:         // есть непокрытые строки? в uncovered curr-файла перемещаем missing, тк сам missing здесь более не нужен
298:         if (!missing.empty())
299:             out.uncovered.push_back(Uncovered{display, std::move(missing)});
300:         // вклад данного файла (всего и покрытые) в итоговую статистику
301:         out.covered += covered;
302:         out.valid += valid;
303:     }
304:     return out;
305: }
306: // ================================================================================================
307: // форматированный вывод статистики для всего проекта
308: std::string format_summary(const Summary& s) {
309:     // ширина этого столбца должна быть не меньше, чем строка "TOTAL", которая там точно будет
310:     std::size_t width = std::string_view("TOTAL").size();
311:     // в итоге выбираем width равный ширине самого широкого пути до файла
312:     for (const auto& f : s.files)
313:         width = std::max(width, f.path.size());
314: 
315:     // шапка и все записи по файлам. и итоговая запись с "всего" и "покрыто" по всему проекту
316:     std::string out = "coverage union (line-based, Cobertura)\n";
317:     for (const auto& f : s.files)
318:         out += format_line(f.path, f.covered, f.valid, width);
319:     out += format_line("TOTAL", s.covered, s.valid, width);
320: 
321:     // если есть непокрытые строки, вывод их с подробностями
322:     if (!s.uncovered.empty()) {
323:         out += "\nuncovered lines:\n";
324:         for (const auto& u : s.uncovered) {
325:             out += "  ";
326:             out += u.path;
327:             out += ": ";
328:             for (std::size_t i = 0; i < u.lines.size(); ++i) {
329:                 if (i != 0)
330:                     out += ", ";
331:                 out += std::to_string(u.lines[i]);
332:             }
333:             out += '\n';
334:         }
335:     }
336:     return out;
337: }
338: // ================================================================================================
339: // если есть файлы, которые должны были быть инструментированы, но не были, - вернуть их список
340: // expected - список путей из манифеста
341: // fold_case должен быть тот же, что и переданный в parse_cobertura
342: std::vector<std::string> missing_expected(const Coverage& cov, std::span<const std::string> expected, bool fold_case) {
343:     std::vector<std::string> missing;
344:     for (const auto& e : expected) {
345:         const auto it = cov.files.find(normalize_key(e, fold_case));
346:         // если файла нет или у него ноль инструментированных строк
347:         if (it == cov.files.end() || it->second.hits.empty())
348:             missing.push_back(e);
349:     }
350:     return missing;
351: }
