 35: std::size_t find_tag_end(std::string_view s, std::size_t start) {
 36:     char quote = '\0';
 37:     for (std::size_t i = start; i < s.size(); ++i) {
 38:         const char c = s[i];
 39:         // quote == '\0' -> мы вне кавычек
 40:         // quote != '\0' -> мы в кавычках
 41:         if (quote != '\0') {
