314: 
315:     // шапка и все записи по файлам. и итоговая запись с "всего" и "покрыто" по всему проекту
316:     std::string out = "coverage union (line-based, Cobertura)\n";
317:     for (const auto& f : s.files)
318:         out += format_line(f.path, f.covered, f.valid, width);
319:     out += format_line("TOTAL", s.covered, s.valid, width);
320: 
321:     // если есть непокрытые строки, вывод их с подробностями
322:     if (!s.uncovered.empty()) {
323:         out += "\nuncovered lines:\n";
324:         for (const auto& u : s.uncovered) {
325:             out += "  ";
326:             out += u.path;
327:             out += ": ";
328:             for (std::size_t i = 0; i < u.lines.size(); ++i) {
329:                 if (i != 0)
330:                     out += ", ";
331:                 out += std::to_string(u.lines[i]);
332:             }
333:             out += '\n';
334:         }
335:     }
336:     return out;
337: }
338: // ================================================================================================
339: // если есть файлы, которые должны были быть инструментированы, но не были, - вернуть их список
340: // expected - список путей из манифеста
341: // fold_case должен быть тот же, что и переданный в parse_cobertura
342: std::vector<std::string> missing_expected(const Coverage& cov, std::span<const std::string> expected, bool fold_case) {
343:     std::vector<std::string> missing;
