345:         const auto it = cov.files.find(normalize_key(e, fold_case));
346:         // если файла нет или у него ноль инструментированных строк
347:         if (it == cov.files.end() || it->second.hits.empty())
348:             missing.push_back(e);
349:     }
350:     return missing;
351: }
