176: // parse_cobertura — алгоритм
177: std::expected<Coverage, ParseError> parse_cobertura(std::string_view xml, bool fold_case) {
178:     Coverage cov;
179:     constexpr std::string_view kClassClose = "</class>";
180:     std::size_t pos = 0;
181:     std::size_t classes = 0;
182:     std::size_t lines = 0;
183:     if (xml.starts_with("\xEF\xBB\xBF"))
184:         pos = 3;
185: 
186:     while (pos < xml.size()) {
187:         std::size_t comment = xml.find("<!--", pos);
188:         if (comment != std::string_view::npos) {
189:             pos = comment + 1;
190:             continue;
191:         }
192:         std::size_t open = xml.find("<class", pos);
193:         if (open == std::string_view::npos)
194:             break;
195:         // проверка что это именно <class...> - сам тэг просто class, после - пробел. иначе - ищем далее
196:         if (!tag_starts(xml, open, "<class")) {
197:             pos = open + 1;
198:             continue;
199:         }
200:         // конц.часть(>) открывающего тега есть? если его нет - "плохой формат"
201:         std::size_t tag_end = find_tag_end(xml, open);
202:         if (tag_end == std::string::npos)
203:             return std::unexpected(make_error(ParseReason::malformed, open, "no closing angle bracket in class tag"));
204:         // вырезать данные м-у < и >
205:         std::string_view tag = xml.substr(open, tag_end - open + 1);
206:         // внутри тега class должен быть атрибут filename. если его нет, этот формат этого файла в этом моменте неверный
207:         auto raw = find_attr(tag, "filename");
208:         if (raw == std::nullopt)
209:             return std::unexpected(make_error(ParseReason::malformed, open, "no filename attribute inside class tag"));
210:         // убрать спецсимволы из пути
211:         std::string path = decode_entities(*raw);
212:         // закрывающий тэг. если его нет, этот формат этого файла в этом моменте неверный
213:         std::size_t close = xml.find("</class>", tag_end);
214:         if (close == std::string::npos)
215:             return std::unexpected(make_error(ParseReason::malformed, tag_end, "no pair </class> after <class>"));
216:         // строки в <class>
217:         std::size_t p = tag_end + 1;
218:         // пространство м-у концом <class ...> и </class>, ожидаем line-s внутри
219:         while (p < close) {
220:             std::size_t l = xml.find("<line", p);
221:             // если не нашли <line или вышли за границы <class ...> и </class>, выходим
222:             if (l == std::string::npos || l > close)
223:                 break;
224:             // должно быть именно <line ...>, не <lines ...>
225:             if (!tag_starts(xml, l, "<line")) {
226:                 // чтобы не застряться, сдвигаемся на 1 и продолжаем поиск
227:                 p = l + 1;
228:                 continue;
229:             }
230:             // конец <line ...; если его нет или он за </class> - это момент формата в данном файле некорректен
231:             std::size_t le = find_tag_end(xml, l);
232:             if (le == std::string::npos || le > close)
233:                 return std::unexpected(make_error(ParseReason::malformed, l, "no /> after <line or /> is too far"));
234:             // внутренность <line ... />
235:             std::string_view ltag = xml.substr(l, le - l + 1);
236: 
237:             // нахождение тегов number и hits внутри <line ... />. если их нет - "плохой формат" в этом файле
238:             auto raw_n = find_attr(ltag, "number");
239:             if (!raw_n)
240:                 return std::unexpected(make_error(ParseReason::malformed, l, "no number attribute inside line tag"));
241:             auto raw_h = find_attr(ltag, "hits");
242:             if (!raw_h)
243:                 return std::unexpected(make_error(ParseReason::malformed, l, "no hits attribute inside line tag"));
244: 
245:             // распознавание чисел после тегов number и hits
246:             std::uint64_t n = 0, h = 0;
247:             // если они распознаны некорректно или n нереальное для строки - "ошибка формата"
248:             if (!parse_u64(*raw_n, n) || !parse_u64(*raw_h, h))
249:                 return std::unexpected(make_error(ParseReason::malformed, l, "line number or hits is not a number"));
250:             if (n == 0 || n > static_cast<std::uint64_t>(std::numeric_limits<int>::max()))
251:                 return std::unexpected(
252:                     make_error(ParseReason::malformed, l, "line number is incorrect: non-positive or more than int"));
253:             // fold_case == true -> приводим к нижнему регистру, тк он неважен; false -> оставляем строку как есть
254:             // и нормализовать слеши
255:             std::string key = normalize_key(path, fold_case);
256: 
257:             // покрытие конкретного файла
258:             FileCoverage& fc = cov.files[key];
259:             // если у данного файла нет пути до него - добавляем
260:             if (fc.display_path.empty())
261:                 fc.display_path = path;
262:             const int line_no = static_cast<int>(n);
263:             fc.hits[line_no] = std::max(line_no, h);
264:             // +1 корректная строка
265:             ++lines;
266:             // переходим за её границу, чтобы не застрять на ней
267:             p = le + 1;
268:         }
269:         // если попали сюда, то прошли все <line ... внутри <class>...</class>
270:         ++classes;
271:         // close стоит на начале </class>, сдвигаемся на kClassClose.size() - за </class>
272:         pos = close + kClassClose.size();
273:     }
274: 
275:     if (classes == 0)
276:         return std::unexpected(make_error(ParseReason::no_classes, 0, "no <class> in report"));
277:     if (lines == 0)
278:         return std::unexpected(make_error(ParseReason::no_lines, 0, "no <line> in report"));
279:     return cov;
280: }
