282: // итоговая статистика по проекту
283: Summary summarize(const Coverage& cov, std::string_view source_root) {
284:     Summary out{};
285:     for (const auto& entry : cov.files) {
286:         const auto& fc = entry.second;
287:         // относит. путь, подсчёт - покрытые и какие именно непокрытые
288:         const std::string display = relative_path(fc.display_path, source_root);
289:         int covered = 0;
290:         std::vector<int> missing;
291:         for (const auto& [line, h] : fc.hits) {
292:             if (h > 0)
293:                 ++covered;
294:             else
295:                 missing.push_back(line);
296:         }
297:         // сколько всего инструментированных строк по данному файлу
298:         const int valid = static_cast<int>(fc.hits.size());
299:         // добавляем в итоговый Summary статистику по текущему файлу
300:         out.files.push_back(FileStat{display, covered, valid});
301:         // есть непокрытые строки? в uncovered curr-файла перемещаем missing, тк сам missing здесь более не нужен
302:         if (!missing.empty())
303:             out.uncovered.push_back(Uncovered{display, std::move(missing)});
304:         // вклад данного файла (всего и покрытые) в итоговую статистику
305:         out.covered += covered;
306:         out.valid += valid;
307:     }
308:     return out;
309: }
310: // ================================================================================================
311: // форматированный вывод статистики для всего проекта
312: std::string format_summary(const Summary& s) {
313:     // ширина этого столбца должна быть не меньше, чем строка "TOTAL", которая там точно будет
314:     std::size_t width = std::string_view("TOTAL").size();
315:     // в итоге выбираем width равный ширине самого широкого пути до файла
316:     for (const auto& f : s.files)
317:         width = std::max(width, f.path.size());
318: 
319:     // шапка и все записи по файлам. и итоговая запись с "всего" и "покрыто" по всему проекту
320:     std::string out = "coverage union (line-based, Cobertura)\n";
321:     for (const auto& f : s.files)
322:         out += format_line(f.path, f.covered, f.valid, width);
323:     out += format_line("TOTAL", s.covered, s.valid, width);
324: 
325:     // если есть непокрытые строки, вывод их с подробностями
326:     if (!s.uncovered.empty()) {
327:         out += "\nuncovered lines:\n";
328:         for (const auto& u : s.uncovered) {
329:             out += "  ";
330:             out += u.path;
331:             out += ": ";
332:             for (std::size_t i = 0; i < u.lines.size(); ++i) {
333:                 if (i != 0)
334:                     out += ", ";
335:                 out += std::to_string(u.lines[i]);
336:             }
337:             out += '\n';
338:         }
339:     }
340:     return out;
341: }
342: // ================================================================================================
343: // если есть файлы, которые должны были быть инструментированы, но не были, - вернуть их список
344: // expected - список путей из манифеста
345: // fold_case должен быть тот же, что и переданный в parse_cobertura
346: std::vector<std::string> missing_expected(const Coverage& cov, std::span<const std::string> expected, bool fold_case) {
347:     std::vector<std::string> missing;
348:     for (const auto& e : expected) {
349:         const auto it = cov.files.find(normalize_key(e, fold_case));
350:         // если файла нет или у него ноль инструментированных строк
351:         if (it == cov.files.end() || it->second.hits.empty())
352:             missing.push_back(e);
353:     }
354:     return missing;
355: }
