 22: bool is_xml_space(char c) { return c == ' ' || c == '\t' || c == '\r' || c == '\n'; }
 23: 
 24: // "самостоятельный" ли тэг?
 25: // <class ...>, <line ...> - да; <classes>/<lines> не должны совпасть
 26: bool tag_starts(std::string_view s, std::size_t p, std::string_view name) {
 27:     if (p + name.size() > s.size() || s.substr(p, name.size()) != name)
 28:         return false;
 29:     if (p + name.size() == s.size())
 30:         return true;
 31:     const char n = s[p + name.size()];
 32:     return is_xml_space(n) || n == '>' || n == '/';
 33: }
