 35: // '>' внутри кавычек не считается концом тега
 36: std::size_t find_tag_end(std::string_view s, std::size_t start) {
 37:     char quote = '\0';
 38:     for (std::size_t i = start; i < s.size(); ++i) {
 39:         const char c = s[i];
 40:         // quote == '\0' -> мы вне кавычек
 41:         // quote != '\0' -> мы в кавычках
 42:         if (quote != '\0') {
 43:             // если при этом текущий символ - также кавычка, то она закрывающая. выходим из кавычек
 44:             if (c == quote)
 45:                 quote = '\0';
 46:         }
 47:         // quote == '\0'. если сейчас кавычка, мы в неё зашли. запоминаем это в quote
 48:         else if (c == '"' || c == '\'') {
 49:             quote = c;
 50:         }
 51:         // quote == '\0', > реально закрывает тэг
 52:         else if (c == '>') {
 53:             return i;
 54:         }
 55:     }
 56:     return std::string_view::npos;
 57: }
