 61: std::optional<std::string_view> find_attr(std::string_view tag, std::string_view name) {
 62:     std::size_t i = 0;
 63:     while (i < tag.size()) {
 64:         while (i < tag.size() && is_xml_space(tag[i]))
 65:             ++i;
