 71:             ++i;
 72:         const std::string_view aname = tag.substr(ns, i - ns);
 73: 
 74:         while (i < tag.size() && is_xml_space(tag[i]))
 75:             ++i;
 76:         if (i >= tag.size() || tag[i] != '=')
 77:             continue;
 78:         ++i;
