243:             c = '/';
244:         if (c == '/' && prev_slash)
245:             continue;
246:         prev_slash = (c == '/');
247:         if (fold_case && c >= 'A' && c <= 'Z')
248:             c = static_cast<char>(c - 'A' + 'a');
249:         out += c;
250:     }
251:     return out;
252: }
253: 
254: std::string relative_path(std::string_view path, std::string_view source_root) {
255:     if (source_root.empty())
256:         return std::string(path);
257:     const std::filesystem::path p{path};
258:     const std::filesystem::path root{source_root};
259:     const std::string rel = p.lexically_relative(root).generic_string();
260:     if (rel.empty() || rel.starts_with(".."))
261:         return std::string(path);
262:     return rel;
263: }
