269: // форматный вывод статистики для отдельного файла
270: std::string format_line(std::string_view path, int covered, int valid, std::size_t width) {
271:     const double pct = valid == 0 ? 0.0 : 100.0 * static_cast<double>(covered) / static_cast<double>(valid);
272:     return std::format("{:<{}} {:>5}/{:<5} {:>7.2f}%\n", path, width, covered, valid, pct);
273: }
