277: // parse_cobertura — алгоритм
278: std::expected<Coverage, ParseError> parse_cobertura(std::string_view xml, bool fold_case) {
279:     Coverage cov;
280:     constexpr std::string_view kClassClose = "</class>";
281:     std::size_t pos = 0;
282:     std::size_t classes = 0;
283:     std::size_t lines = 0;
284:     if (xml.starts_with("\xEF\xBB\xBF"))
285:         pos = 3;
286: 
287:     while (pos < xml.size()) {
288:         std::size_t comment = xml.find("<!--", pos);
289:         if (comment != std::string_view::npos) {
290:             pos = comment + 1;
291:             continue;
292:         }
293:         std::size_t open = xml.find("<class", pos);
294:         if (open == std::string_view::npos)
295:             break;
296:         // проверка что это именно <class...> - сам тэг просто class, после - пробел. иначе - ищем далее
297:         if (!tag_starts(xml, open, "<class")) {
298:             pos = open + 1;
299:             continue;
300:         }
301:         // конц.часть(>) открывающего тега есть? если его нет - "плохой формат"
302:         std::size_t tag_end = find_tag_end(xml, open);
303:         if (tag_end == std::string::npos)
304:             return std::unexpected(make_error(ParseReason::malformed, open, "no closing angle bracket in class tag"));
305:         // вырезать данные м-у < и >
306:         std::string_view tag = xml.substr(open, tag_end - open + 1);
307:         // внутри тега class должен быть атрибут filename. если его нет, этот формат этого файла в этом моменте неверный
308:         auto raw = find_attr(tag, "filename");
309:         if (raw == std::nullopt)
310:             return std::unexpected(make_error(ParseReason::malformed, open, "no filename attribute inside class tag"));
311:         // убрать спецсимволы из пути
312:         std::string path = decode_entities(*raw);
313:         // закрывающий тэг. если его нет, этот формат этого файла в этом моменте неверный
314:         std::size_t close = xml.find("</class>", tag_end);
315:         if (close == std::string::npos)
316:             return std::unexpected(make_error(ParseReason::malformed, tag_end, "no pair </class> after <class>"));
317:         // строки в <class>
318:         std::size_t p = tag_end + 1;
319:         // пространство м-у концом <class ...> и </class>, ожидаем line-s внутри
320:         while (p < close) {
321:             std::size_t l = xml.find("<line", p);
322:             // если не нашли <line или вышли за границы <class ...> и </class>, выходим
323:             if (l == std::string::npos || l > close)
324:                 break;
325:             // должно быть именно <line ...>, не <lines ...>
326:             if (!tag_starts(xml, l, "<line")) {
327:                 // чтобы не застряться, сдвигаемся на 1 и продолжаем поиск
328:                 p = l + 1;
329:                 continue;
330:             }
331:             // конец <line ...; если его нет или он за </class> - это момент формата в данном файле некорректен
332:             std::size_t le = find_tag_end(xml, l);
333:             if (le == std::string::npos || le > close)
334:                 return std::unexpected(make_error(ParseReason::malformed, l, "no /> after <line or /> is too far"));
335:             // внутренность <line ... />
336:             std::string_view ltag = xml.substr(l, le - l + 1);
337: 
338:             // нахождение тегов number и hits внутри <line ... />. если их нет - "плохой формат" в этом файле
339:             auto raw_n = find_attr(ltag, "number");
340:             if (!raw_n)
341:                 return std::unexpected(make_error(ParseReason::malformed, l, "no number attribute inside line tag"));
342:             auto raw_h = find_attr(ltag, "hits");
343:             if (!raw_h)
344:                 return std::unexpected(make_error(ParseReason::malformed, l, "no hits attribute inside line tag"));
345: 
346:             // распознавание чисел после тегов number и hits
347:             std::uint64_t n = 0, h = 0;
348:             // если они распознаны некорректно или n нереальное для строки - "ошибка формата"
349:             if (!parse_u64(*raw_n, n) || !parse_u64(*raw_h, h))
350:                 return std::unexpected(make_error(ParseReason::malformed, l, "line number or hits is not a number"));
351:             if (n == 0 || n > static_cast<std::uint64_t>(std::numeric_limits<int>::max()))
352:                 return std::unexpected(
353:                     make_error(ParseReason::malformed, l, "line number is incorrect: non-positive or more than int"));
354:             // fold_case == true -> приводим к нижнему регистру, тк он неважен; false -> оставляем строку как есть
355:             // и нормализовать слеши
356:             std::string key = normalize_key(path, fold_case);
357: 
358:             // покрытие конкретного файла
359:             FileCoverage& fc = cov.files[key];
360:             // если у данного файла нет пути до него - добавляем
361:             if (fc.display_path.empty())
362:                 fc.display_path = path;
363:             const int line_no = static_cast<int>(n);
364:             fc.hits[line_no] = std::max(fc.hits[line_no], h);
365:             // +1 корректная строка
366:             ++lines;
367:             // переходим за её границу, чтобы не застрять на ней
368:             p = le + 1;
369:         }
370:         // если попали сюда, то прошли все <line ... внутри <class>...</class>
371:         ++classes;
372:         // close стоит на начале </class>, сдвигаемся на kClassClose.size() - за </class>
373:         pos = close + kClassClose.size();
374:     }
375: 
376:     if (classes == 0)
377:         return std::unexpected(make_error(ParseReason::no_classes, 0, "no <class> in report"));
378:     if (lines == 0)
379:         return std::unexpected(make_error(ParseReason::no_lines, 0, "no <line> in report"));
380:     return cov;
381: }
