383: // итоговая статистика по проекту
384: Summary summarize(const Coverage& cov, std::string_view source_root) {
385:     Summary out{};
386:     for (const auto& entry : cov.files) {
387:         const auto& fc = entry.second;
388:         // относит. путь, подсчёт - покрытые и какие именно непокрытые
389:         const std::string display = relative_path(fc.display_path, source_root);
390:         int covered = 0;
391:         std::vector<int> missing;
392:         for (const auto& [line, h] : fc.hits) {
393:             if (h > 0)
394:                 ++covered;
395:             else
396:                 missing.push_back(line);
397:         }
398:         // сколько всего инструментированных строк по данному файлу
399:         const int valid = static_cast<int>(fc.hits.size());
400:         // добавляем в итоговый Summary статистику по текущему файлу
401:         out.files.push_back(FileStat{display, covered, valid});
402:         // есть непокрытые строки? в uncovered curr-файла перемещаем missing, тк сам missing здесь более не нужен
403:         if (!missing.empty())
404:             out.uncovered.push_back(Uncovered{display, std::move(missing)});
405:         // вклад данного файла (всего и покрытые) в итоговую статистику
406:         out.covered += covered;
407:         out.valid += valid;
408:     }
409:     return out;
410: }
411: // ================================================================================================
412: // форматированный вывод статистики для всего проекта
413: std::string format_summary(const Summary& s) {
414:     // ширина этого столбца должна быть не меньше, чем строка "TOTAL", которая там точно будет
415:     std::size_t width = std::string_view("TOTAL").size();
416:     // в итоге выбираем width равный ширине самого широкого пути до файла
417:     for (const auto& f : s.files)
418:         width = std::max(width, f.path.size());
419: 
420:     // шапка и все записи по файлам. и итоговая запись с "всего" и "покрыто" по всему проекту
421:     std::string out = "coverage union (line-based, Cobertura)\n";
422:     for (const auto& f : s.files)
423:         out += format_line(f.path, f.covered, f.valid, width);
424:     out += format_line("TOTAL", s.covered, s.valid, width);
425: 
426:     // если есть непокрытые строки, вывод их с подробностями
427:     if (!s.uncovered.empty()) {
428:         out += "\nuncovered lines:\n";
429:         for (const auto& u : s.uncovered) {
430:             out += "  ";
431:             out += u.path;
432:             out += ": ";
433:             for (std::size_t i = 0; i < u.lines.size(); ++i) {
434:                 if (i != 0)
435:                     out += ", ";
436:                 out += std::to_string(u.lines[i]);
437:             }
438:             out += '\n';
439:         }
440:     }
441:     return out;
442: }
443: // ================================================================================================
444: // если есть файлы, которые должны были быть инструментированы, но не были, - вернуть их список
445: // expected - список путей из манифеста
446: // fold_case должен быть тот же, что и переданный в parse_cobertura
447: std::vector<std::string> missing_expected(const Coverage& cov, std::span<const std::string> expected, bool fold_case) {
448:     std::vector<std::string> missing;
449:     for (const auto& e : expected) {
450:         const auto it = cov.files.find(normalize_key(e, fold_case));
451:         // если файла нет или у него ноль инструментированных строк
452:         if (it == cov.files.end() || it->second.hits.empty())
453:             missing.push_back(e);
454:     }
455:     return missing;
456: }
