 22: bool is_xml_space(char c) { return c == ' ' || c == '\t' || c == '\r' || c == '\n'; }
 23: 
 24: struct Tag {
 25:     std::string_view name; // "class", "line", "package", ...
 26:     std::string_view text; // "<class ...>", "</class>", "<line ... />"
 27:     std::size_t begin;     // индекс '<'
