 33: // обособленный поиск тега - не считаем комментарии и строки, которые xml-парсер игнорирует
 34: class TagReader {
 35: public:
 36:     explicit TagReader(std::string_view xml);
 37: 
 38:     // true  - тег прочитан
 39:     // false - конец документа
 40:     // unexpected - malformed
 41:     std::expected<bool, ParseError> next(Tag& out);
 42: 
 43: private:
 44:     std::string_view xml_;
 45:     std::size_t pos_ = 0;
 46: 
 47:     /*
 48:     next():
 49:     - ищет <;
 50:     - <!-- -> ищет -->; если нет — malformed; иначе прыгает за -->;
 51:     - <? -> ищет ?>; если нет — malformed; иначе прыгает (XML-декларация);
 52:     - <! не комментарий (DOCTYPE, CDATA) -> malformed;
 53:     - иначе разбирает тег: find_tag_end (quote-aware), имя, closing, self_closing;
 54:     - tag_starts после этого не нужен.
 55:     */
 56:     std::expected<bool, ParseError> next(Tag& out) {
 57:         std::size_t start_open_angle = xml_.find("<", pos_);
 58:         // если начала открывающего тега больше нет, теги закончились -> конец документа
 59:         if (start_open_angle == std::string::npos)
 60:             return false;
 61: 
 62:         // какой след. тег: декларация/комментарий - ок, DOCTYPE/CDATA - падаем, тут это неподдерживаемый синтаксис
 63:         // comment
 64:         if (xml_.substr(pos_, 4) == "<!--") {
 65:             ++pos;
 66:             std::size_t comment_closing = xml_.find("-->", pos_);
 67:             if (comment_closing == std::string::npos) {
 68:                 return std::unexpected(make_error(ParseReason::malformed, pos_, "no closing sequence (-->) in comment"));
 69:             }
 70:             // если нашли закрытие комментария, передвигаемся за него 
 71:             pos_ = comment_closing + std::string_view("-->").size();
 72: continue;
 73:         }
 74:         // declaration 
 75:         else if (xml_.substr(pos_, 2) == "<?") {
 76:             ++pos_;
 77:             std::size_t declaration_closing = xml_.find("?>", pos_);
 78:             if (declaration_closing == std::string::npos) {
 79:                 return std::unexpected(
 80:                     make_error(ParseReason::malformed, pos_, "no closing sequence (?>) in declaration"));
 81:             }
 82:             // если нашли закрытие декларации, передвигаемся за неё 
 83:             pos_ = declaration_closing + std::string_view("?>").size();
 84: continue;
 85:         }
 86:         // <!DOCTYPE.../<![CDATA... - не поддерживаем
 87:         else if (xml_.substr(pos_, 2) == "<!") {
 88:             return std::unexpected(
 89:                 make_error(ParseReason::malformed, pos_, "unsupported syntaxis (DOCTYPE for CDATA) for this parser"));
 90:         }
 91:         // иначе - это какой-то тег, надо его разобрать. текущий pos_ - на <
 92:         else {
 93:         // находим > этого тега, если тег незакрыт - "плохой формат"
 94:         std::size_t tag_closure = find_tag_end(xml_, pos_);  
 95:         if (tag_closure == std::string::npos) {
 96:                 return std::unexpected(
 97:                     make_error(ParseReason::malformed, tag_closure, "no closing bracket angle in opening tag"));
 98:         }
 99: 
100:         // если > есть, тег нормальный, выбираем его содержимое - м-у < и >
101:         std::string_view text = xml.substr(pos_ + 1, tag_closure - pos_)
102:         out.text = text;
103:         // фиксируем начало и конец самого тега
104:         out.begin = pos_;
105:         out.end = tag_closure;
106: 
107:         // проверяем, это самозакрывающийся тег типа <line.../> или нет?
108:         if (xml.substr(tag_closure - 1, tag_closure) == "/"){
109:             // самозакрывающийся
110:             out.closing = false;
111:             out.self_closing = true;
112:         } else {
113:            // имеет парный закрывающий, надо его найти
114:             out.closing = true;
115:             out.self_closing = false;
116:         }
117: 
118:         // TODO ПОИСК ИМЕНИ ТЕГА
119: 
120:         } 
121:     }
122: };
123: 
124: // "самостоятельный" ли тег?
125: // <class ...>, <line ...> - да; <classes>/<lines> не должны совпасть
126: bool tag_starts(std::string_view s, std::size_t p, std::string_view name) {
127:     if (p + name.size() > s.size() || s.substr(p, name.size()) != name)
128:         return false;
129:     if (p + name.size() == s.size())
130:         return true;
131:     const char n = s[p + name.size()];
132:     return is_xml_space(n) || n == '>' || n == '/';
133: }
134: 
135: // '>' внутри кавычек не считается концом тега
136: std::size_t find_tag_end(std::string_view s, std::size_t start) {
137:     char quote = '\0';
138:     for (std::size_t i = start; i < s.size(); ++i) {
139:         const char c = s[i];
140:         // quote == '\0' -> мы вне кавычек
141:         // quote != '\0' -> мы в кавычках
142:         if (quote != '\0') {
143:             // если при этом текущий символ - также кавычка, то она закрывающая. выходим из кавычек
144:             if (c == quote)
145:                 quote = '\0';
146:         }
147:         // quote == '\0'. если сейчас кавычка, мы в неё зашли. запоминаем это в quote
148:         else if (c == '"' || c == '\'') {
149:             quote = c;
150:         }
151:         // quote == '\0', > реально закрывает тэг
152:         else if (c == '>') {
153:             return i;
154:         }
155:     }
156:     return std::string_view::npos;
157: }
