159: // порядок атрибутов не важен; кавычки одинарные/двойные
160: // optional - value that may or may not be present
161: std::optional<std::string_view> find_attr(std::string_view tag, std::string_view name) {
162:     std::size_t i = 0;
163:     while (i < tag.size()) {
164:         while (i < tag.size() && is_xml_space(tag[i]))
165:             ++i;
166:         if (i >= tag.size() || tag[i] == '>' || tag[i] == '/')
167:             break;
168: 
169:         const std::size_t ns = i;
170:         while (i < tag.size() && !is_xml_space(tag[i]) && tag[i] != '=' && tag[i] != '>' && tag[i] != '/')
171:             ++i;
172:         const std::string_view aname = tag.substr(ns, i - ns);
173: 
174:         while (i < tag.size() && is_xml_space(tag[i]))
175:             ++i;
176:         if (i >= tag.size() || tag[i] != '=')
177:             continue;
178:         ++i;
179:         while (i < tag.size() && is_xml_space(tag[i]))
180:             ++i;
181:         if (i >= tag.size() || (tag[i] != '"' && tag[i] != '\''))
182:             return std::nullopt;
183: 
184:         const char quote = tag[i++];
185:         const std::size_t vs = i;
186:         while (i < tag.size() && tag[i] != quote)
187:             ++i;
188:         if (i >= tag.size())
189:             return std::nullopt;
190: 
191:         const std::string_view value = tag.substr(vs, i - vs);
192:         ++i;
193:         if (aname == name)
194:             return value;
195:     }
196:     return std::nullopt;
197: }
