199: std::string decode_entities(std::string_view raw) {
200:     std::string out;
201:     out.reserve(raw.size());
202:     // в xml спецсимволы лежат как &имя; (& будет &amp; < &lt; и т.д.)
203:     // чтобы это не испортило пути, спецсимв. -> обычные символы
204:     for (std::size_t i = 0; i < raw.size(); ++i) {
205:         if (raw[i] != '&') {
206:             out += raw[i];
207:         } else if (raw.substr(i, 5) == "&amp;") {
208:             out += '&';
209:             i += 4;
210:         } else if (raw.substr(i, 4) == "&lt;") {
211:             out += '<';
212:             i += 3;
213:         } else if (raw.substr(i, 4) == "&gt;") {
214:             out += '>';
215:             i += 3;
216:         } else if (raw.substr(i, 6) == "&quot;") {
217:             out += '"';
218:             i += 5;
219:         } else if (raw.substr(i, 6) == "&apos;") {
220:             out += '\'';
221:             i += 5;
222:         } else {
223:             out += raw[i];
224:         }
225:     }
226:     return out;
227: }
