229: bool parse_u64(std::string_view s, std::uint64_t& out) {
230:     if (s.empty())
231:         return false;
232:     const auto [ptr, ec] = std::from_chars(s.data(), s.data() + s.size(), out);
233:     return ec == std::errc{} && ptr == s.data() + s.size();
234: }
