236: // \ -> /, схлопнуть //, на Windows lower-case
237: std::string normalize_key(std::string_view path, bool fold_case) {
238:     std::string out;
239:     out.reserve(path.size());
240:     bool prev_slash = false;
241:     for (char c : path) {
242:         if (c == '\\')
243:             c = '/';
244:         if (c == '/' && prev_slash)
245:             continue;
246:         prev_slash = (c == '/');
247:         if (fold_case && c >= 'A' && c <= 'Z')
248:             c = static_cast<char>(c - 'A' + 'a');
249:         out += c;
250:     }
251:     return out;
252: }
