 96:         out.end = tag_end;
 97:         out.text = xml_.substr(pos_, tag_end - pos_ + 1);
 98:         out.self_closing = xml_[tag_end - 1] == '/';
 99:         out.closing = false; // заглушка, закрытие тега находится отдельно, в автомате
100:         // TODO out.name
101:         // тег валидный, прыгаем за него и выходим из цикла - т.к. next tag найден
102:         pos_ = tag_end + 1;
103:         return true;
104:     }
105:     return false;
106: }
107: 
108: // "самостоятельный" ли тег?
109: // <class ...>, <line ...> - да; <classes>/<lines> не должны совпасть
110: bool tag_starts(std::string_view s, std::size_t p, std::string_view name) {
111:     if (p + name.size() > s.size() || s.substr(p, name.size()) != name)
112:         return false;
113:     if (p + name.size() == s.size())
114:         return true;
115:     const char n = s[p + name.size()];
116:     return is_xml_space(n) || n == '>' || n == '/';
117: }
118: 
119: // '>' внутри кавычек не считается концом тега
120: std::size_t find_tag_end(std::string_view s, std::size_t start) {
121:     char quote = '\0';
122:     for (std::size_t i = start; i < s.size(); ++i) {
123:         const char c = s[i];
124:         // quote == '\0' -> мы вне кавычек
125:         // quote != '\0' -> мы в кавычках
126:         if (quote != '\0') {
127:             // если при этом текущий символ - также кавычка, то она закрывающая. выходим из кавычек
128:             if (c == quote)
129:                 quote = '\0';
130:         }
131:         // quote == '\0'. если сейчас кавычка, мы в неё зашли. запоминаем это в quote
132:         else if (c == '"' || c == '\'') {
133:             quote = c;
134:         }
135:         // quote == '\0', > реально закрывает тэг
136:         else if (c == '>') {
137:             return i;
138:         }
139:     }
140:     return std::string_view::npos;
141: }
142: 
143: // порядок атрибутов не важен; кавычки одинарные/двойные
144: // optional - value that may or may not be present
145: std::optional<std::string_view> find_attr(std::string_view tag, std::string_view name) {
146:     std::size_t i = 0;
147:     while (i < tag.size()) {
148:         while (i < tag.size() && is_xml_space(tag[i]))
149:             ++i;
150:         if (i >= tag.size() || tag[i] == '>' || tag[i] == '/')
151:             break;
152: 
153:         const std::size_t ns = i;
154:         while (i < tag.size() && !is_xml_space(tag[i]) && tag[i] != '=' && tag[i] != '>' && tag[i] != '/')
155:             ++i;
156:         const std::string_view aname = tag.substr(ns, i - ns);
157: 
158:         while (i < tag.size() && is_xml_space(tag[i]))
159:             ++i;
160:         if (i >= tag.size() || tag[i] != '=')
161:             continue;
162:         ++i;
163:         while (i < tag.size() && is_xml_space(tag[i]))
164:             ++i;
165:         if (i >= tag.size() || (tag[i] != '"' && tag[i] != '\''))
166:             return std::nullopt;
167: 
168:         const char quote = tag[i++];
169:         const std::size_t vs = i;
170:         while (i < tag.size() && tag[i] != quote)
171:             ++i;
172:         if (i >= tag.size())
173:             return std::nullopt;
174: 
175:         const std::string_view value = tag.substr(vs, i - vs);
176:         ++i;
177:         if (aname == name)
178:             return value;
179:     }
180:     return std::nullopt;
181: }
182: 
183: std::string decode_entities(std::string_view raw) {
184:     std::string out;
185:     out.reserve(raw.size());
186:     // в xml спецсимволы лежат как &имя; (& будет &amp; < &lt; и т.д.)
187:     // чтобы это не испортило пути, спецсимв. -> обычные символы
188:     for (std::size_t i = 0; i < raw.size(); ++i) {
189:         if (raw[i] != '&') {
190:             out += raw[i];
191:         } else if (raw.substr(i, 5) == "&amp;") {
192:             out += '&';
193:             i += 4;
194:         } else if (raw.substr(i, 4) == "&lt;") {
195:             out += '<';
196:             i += 3;
197:         } else if (raw.substr(i, 4) == "&gt;") {
198:             out += '>';
199:             i += 3;
200:         } else if (raw.substr(i, 6) == "&quot;") {
201:             out += '"';
202:             i += 5;
203:         } else if (raw.substr(i, 6) == "&apos;") {
204:             out += '\'';
205:             i += 5;
206:         } else {
207:             out += raw[i];
208:         }
209:     }
210:     return out;
211: }
212: 
213: bool parse_u64(std::string_view s, std::uint64_t& out) {
214:     if (s.empty())
215:         return false;
216:     const auto [ptr, ec] = std::from_chars(s.data(), s.data() + s.size(), out);
217:     return ec == std::errc{} && ptr == s.data() + s.size();
218: }
219: 
220: // \ -> /, схлопнуть //, на Windows lower-case
221: std::string normalize_key(std::string_view path, bool fold_case) {
222:     std::string out;
223:     out.reserve(path.size());
224:     bool prev_slash = false;
225:     for (char c : path) {
226:         if (c == '\\')
227:             c = '/';
228:         if (c == '/' && prev_slash)
229:             continue;
230:         prev_slash = (c == '/');
231:         if (fold_case && c >= 'A' && c <= 'Z')
232:             c = static_cast<char>(c - 'A' + 'a');
233:         out += c;
234:     }
235:     return out;
236: }
237: 
238: std::string relative_path(std::string_view path, std::string_view source_root) {
239:     if (source_root.empty())
240:         return std::string(path);
241:     const std::filesystem::path p{path};
242:     const std::filesystem::path root{source_root};
243:     const std::string rel = p.lexically_relative(root).generic_string();
244:     if (rel.empty() || rel.starts_with(".."))
245:         return std::string(path);
246:     return rel;
247: }
