249: ParseError make_error(ParseReason reason, std::size_t offset, std::string what) {
250:     return ParseError{reason, offset, std::move(what)};
251: }
252: 
253: // форматный вывод статистики для отдельного файла
254: std::string format_line(std::string_view path, int covered, int valid, std::size_t width) {
255:     const double pct = valid == 0 ? 0.0 : 100.0 * static_cast<double>(covered) / static_cast<double>(valid);
256:     return std::format("{:<{}} {:>5}/{:<5} {:>7.2f}%\n", path, width, covered, valid, pct);
257: }
