260: // ================================================================================================
261: // parse_cobertura — алгоритм
262: std::expected<Coverage, ParseError> parse_cobertura(std::string_view xml, bool fold_case) {
263:     Coverage cov;
264:     constexpr std::string_view kClassClose = "</class>";
265:     std::size_t pos = 0;
266:     std::size_t classes = 0;
267:     std::size_t lines = 0;
268:     if (xml.starts_with("\xEF\xBB\xBF"))
269:         pos = 3;
270: 
271:     while (pos < xml.size()) {
272:         std::size_t comment = xml.find("<!--", pos);
273:         if (comment != std::string_view::npos) {
274:             pos = comment + 1;
275:             continue;
276:         }
277:         std::size_t open = xml.find("<class", pos);
278:         if (open == std::string_view::npos)
279:             break;
280:         // проверка что это именно <class...> - сам тэг просто class, после - пробел. иначе - ищем далее
281:         if (!tag_starts(xml, open, "<class")) {
282:             pos = open + 1;
283:             continue;
284:         }
285:         // конц.часть(>) открывающего тега есть? если его нет - "плохой формат"
286:         std::size_t tag_end = find_tag_end(xml, open);
287:         if (tag_end == std::string::npos)
288:             return std::unexpected(make_error(ParseReason::malformed, open, "no closing angle bracket in class tag"));
289:         // вырезать данные м-у < и >
290:         std::string_view tag = xml.substr(open, tag_end - open + 1);
291:         // внутри тега class должен быть атрибут filename. если его нет, этот формат этого файла в этом моменте неверный
292:         auto raw = find_attr(tag, "filename");
293:         if (raw == std::nullopt)
294:             return std::unexpected(make_error(ParseReason::malformed, open, "no filename attribute inside class tag"));
295:         // убрать спецсимволы из пути
296:         std::string path = decode_entities(*raw);
297:         // закрывающий тэг. если его нет, этот формат этого файла в этом моменте неверный
298:         std::size_t close = xml.find("</class>", tag_end);
299:         if (close == std::string::npos)
300:             return std::unexpected(make_error(ParseReason::malformed, tag_end, "no pair </class> after <class>"));
301:         // строки в <class>
302:         std::size_t p = tag_end + 1;
303:         // пространство м-у концом <class ...> и </class>, ожидаем line-s внутри
304:         while (p < close) {
305:             std::size_t l = xml.find("<line", p);
306:             // если не нашли <line или вышли за границы <class ...> и </class>, выходим
307:             if (l == std::string::npos || l > close)
308:                 break;
309:             // должно быть именно <line ...>, не <lines ...>
310:             if (!tag_starts(xml, l, "<line")) {
311:                 // чтобы не застряться, сдвигаемся на 1 и продолжаем поиск
312:                 p = l + 1;
313:                 continue;
314:             }
315:             // конец <line ...; если его нет или он за </class> - это момент формата в данном файле некорректен
316:             std::size_t le = find_tag_end(xml, l);
317:             if (le == std::string::npos || le > close)
318:                 return std::unexpected(make_error(ParseReason::malformed, l, "no /> after <line or /> is too far"));
319:             // внутренность <line ... />
320:             std::string_view ltag = xml.substr(l, le - l + 1);
321: 
322:             // нахождение тегов number и hits внутри <line ... />. если их нет - "плохой формат" в этом файле
323:             auto raw_n = find_attr(ltag, "number");
324:             if (!raw_n)
325:                 return std::unexpected(make_error(ParseReason::malformed, l, "no number attribute inside line tag"));
326:             auto raw_h = find_attr(ltag, "hits");
327:             if (!raw_h)
328:                 return std::unexpected(make_error(ParseReason::malformed, l, "no hits attribute inside line tag"));
329: 
330:             // распознавание чисел после тегов number и hits
331:             std::uint64_t n = 0, h = 0;
332:             // если они распознаны некорректно или n нереальное для строки - "ошибка формата"
333:             if (!parse_u64(*raw_n, n) || !parse_u64(*raw_h, h))
334:                 return std::unexpected(make_error(ParseReason::malformed, l, "line number or hits is not a number"));
335:             if (n == 0 || n > static_cast<std::uint64_t>(std::numeric_limits<int>::max()))
336:                 return std::unexpected(
337:                     make_error(ParseReason::malformed, l, "line number is incorrect: non-positive or more than int"));
338:             // fold_case == true -> приводим к нижнему регистру, тк он неважен; false -> оставляем строку как есть
339:             // и нормализовать слеши
340:             std::string key = normalize_key(path, fold_case);
341: 
342:             // покрытие конкретного файла
343:             FileCoverage& fc = cov.files[key];
344:             // если у данного файла нет пути до него - добавляем
345:             if (fc.display_path.empty())
346:                 fc.display_path = path;
347:             const int line_no = static_cast<int>(n);
348:             fc.hits[line_no] = std::max(fc.hits[line_no], h);
349:             // +1 корректная строка
350:             ++lines;
351:             // переходим за её границу, чтобы не застрять на ней
352:             p = le + 1;
353:         }
354:         // если попали сюда, то прошли все <line ... внутри <class>...</class>
355:         ++classes;
356:         // close стоит на начале </class>, сдвигаемся на kClassClose.size() - за </class>
357:         pos = close + kClassClose.size();
358:     }
359: 
360:     if (classes == 0)
361:         return std::unexpected(make_error(ParseReason::no_classes, 0, "no <class> in report"));
362:     if (lines == 0)
363:         return std::unexpected(make_error(ParseReason::no_lines, 0, "no <line> in report"));
364:     return cov;
365: }
366: // ================================================================================================
367: // итоговая статистика по проекту
368: Summary summarize(const Coverage& cov, std::string_view source_root) {
369:     Summary out{};
370:     for (const auto& entry : cov.files) {
371:         const auto& fc = entry.second;
372:         // относит. путь, подсчёт - покрытые и какие именно непокрытые
373:         const std::string display = relative_path(fc.display_path, source_root);
374:         int covered = 0;
375:         std::vector<int> missing;
376:         for (const auto& [line, h] : fc.hits) {
377:             if (h > 0)
378:                 ++covered;
379:             else
380:                 missing.push_back(line);
381:         }
382:         // сколько всего инструментированных строк по данному файлу
383:         const int valid = static_cast<int>(fc.hits.size());
384:         // добавляем в итоговый Summary статистику по текущему файлу
385:         out.files.push_back(FileStat{display, covered, valid});
386:         // есть непокрытые строки? в uncovered curr-файла перемещаем missing, тк сам missing здесь более не нужен
387:         if (!missing.empty())
388:             out.uncovered.push_back(Uncovered{display, std::move(missing)});
389:         // вклад данного файла (всего и покрытые) в итоговую статистику
390:         out.covered += covered;
391:         out.valid += valid;
392:     }
393:     return out;
394: }
395: // ================================================================================================
396: // форматированный вывод статистики для всего проекта
397: std::string format_summary(const Summary& s) {
398:     // ширина этого столбца должна быть не меньше, чем строка "TOTAL", которая там точно будет
399:     std::size_t width = std::string_view("TOTAL").size();
400:     // в итоге выбираем width равный ширине самого широкого пути до файла
401:     for (const auto& f : s.files)
402:         width = std::max(width, f.path.size());
403: 
404:     // шапка и все записи по файлам. и итоговая запись с "всего" и "покрыто" по всему проекту
405:     std::string out = "coverage union (line-based, Cobertura)\n";
406:     for (const auto& f : s.files)
407:         out += format_line(f.path, f.covered, f.valid, width);
408:     out += format_line("TOTAL", s.covered, s.valid, width);
409: 
410:     // если есть непокрытые строки, вывод их с подробностями
411:     if (!s.uncovered.empty()) {
412:         out += "\nuncovered lines:\n";
413:         for (const auto& u : s.uncovered) {
414:             out += "  ";
415:             out += u.path;
416:             out += ": ";
417:             for (std::size_t i = 0; i < u.lines.size(); ++i) {
418:                 if (i != 0)
419:                     out += ", ";
420:                 out += std::to_string(u.lines[i]);
421:             }
422:             out += '\n';
423:         }
424:     }
425:     return out;
426: }
427: // ================================================================================================
428: // если есть файлы, которые должны были быть инструментированы, но не были, - вернуть их список
429: // expected - список путей из манифеста
430: // fold_case должен быть тот же, что и переданный в parse_cobertura
431: std::vector<std::string> missing_expected(const Coverage& cov, std::span<const std::string> expected, bool fold_case) {
432:     std::vector<std::string> missing;
433:     for (const auto& e : expected) {
434:         const auto it = cov.files.find(normalize_key(e, fold_case));
435:         // если файла нет или у него ноль инструментированных строк
436:         if (it == cov.files.end() || it->second.hits.empty())
437:             missing.push_back(e);
438:     }
439:     return missing;
440: }
