108: // "самостоятельный" ли тег?
109: // <class ...>, <line ...> - да; <classes>/<lines> не должны совпасть
110: bool tag_starts(std::string_view s, std::size_t p, std::string_view name) {
111:     if (p + name.size() > s.size() || s.substr(p, name.size()) != name)
112:         return false;
113:     if (p + name.size() == s.size())
114:         return true;
115:     const char n = s[p + name.size()];
