194:         while (i < tag.size() && !is_xml_space(tag[i]) && tag[i] != '=' && tag[i] != '>' && tag[i] != '/')
195:             ++i;
196:         const std::string_view aname = tag.substr(ns, i - ns);
197: 
198:         while (i < tag.size() && is_xml_space(tag[i]))
199:             ++i;
200:         if (i >= tag.size() || tag[i] != '=')
201:             continue;
202:         ++i;
203:         while (i < tag.size() && is_xml_space(tag[i]))
204:             ++i;
205:         if (i >= tag.size() || (tag[i] != '"' && tag[i] != '\''))
206:             return std::nullopt;
207: 
208:         const char quote = tag[i++];
209:         const std::size_t vs = i;
210:         while (i < tag.size() && tag[i] != quote)
211:             ++i;
212:         if (i >= tag.size())
213:             return std::nullopt;
214: 
215:         const std::string_view value = tag.substr(vs, i - vs);
216:         ++i;
217:         if (aname == name)
218:             return value;
219:     }
220:     return std::nullopt;
221: }
