223: std::string decode_entities(std::string_view raw) {
224:     std::string out;
225:     out.reserve(raw.size());
226:     // в xml спецсимволы лежат как &имя; (& будет &amp; < &lt; и т.д.)
227:     // чтобы это не испортило пути, спецсимв. -> обычные символы
228:     for (std::size_t i = 0; i < raw.size(); ++i) {
229:         if (raw[i] != '&') {
230:             out += raw[i];
231:         } else if (raw.substr(i, 5) == "&amp;") {
232:             out += '&';
233:             i += 4;
234:         } else if (raw.substr(i, 4) == "&lt;") {
235:             out += '<';
236:             i += 3;
237:         } else if (raw.substr(i, 4) == "&gt;") {
238:             out += '>';
239:             i += 3;
240:         } else if (raw.substr(i, 6) == "&quot;") {
241:             out += '"';
242:             i += 5;
243:         } else if (raw.substr(i, 6) == "&apos;") {
244:             out += '\'';
245:             i += 5;
246:         } else {
247:             out += raw[i];
248:         }
249:     }
250:     return out;
251: }
