253: bool parse_u64(std::string_view s, std::uint64_t& out) {
254:     if (s.empty())
255:         return false;
256:     const auto [ptr, ec] = std::from_chars(s.data(), s.data() + s.size(), out);
257:     return ec == std::errc{} && ptr == s.data() + s.size();
258: }
