260: // \ -> /, схлопнуть //, на Windows lower-case
261: std::string normalize_key(std::string_view path, bool fold_case) {
262:     std::string out;
263:     out.reserve(path.size());
264:     bool prev_slash = false;
265:     for (char c : path) {
266:         if (c == '\\')
267:             c = '/';
268:         if (c == '/' && prev_slash)
269:             continue;
270:         prev_slash = (c == '/');
271:         if (fold_case && c >= 'A' && c <= 'Z')
272:             c = static_cast<char>(c - 'A' + 'a');
273:         out += c;
274:     }
275:     return out;
276: }
