500: // итоговая статистика по проекту
501: Summary summarize(const Coverage& cov, std::string_view source_root) {
502:     Summary out{};
503:     for (const auto& entry : cov.files) {
504:         const auto& fc = entry.second;
505:         // относит. путь, подсчёт - покрытые и какие именно непокрытые
506:         const std::string display = relative_path(fc.display_path, source_root);
507:         int covered = 0;
508:         std::vector<int> missing;
509:         for (const auto& [line, h] : fc.hits) {
510:             if (h > 0)
511:                 ++covered;
512:             else
513:                 missing.push_back(line);
514:         }
515:         // сколько всего инструментированных строк по данному файлу
516:         const int valid = static_cast<int>(fc.hits.size());
517:         // добавляем в итоговый Summary статистику по текущему файлу
518:         out.files.push_back(FileStat{display, covered, valid});
519:         // есть непокрытые строки? в uncovered curr-файла перемещаем missing, тк сам missing здесь более не нужен
520:         if (!missing.empty())
521:             out.uncovered.push_back(Uncovered{display, std::move(missing)});
522:         // вклад данного файла (всего и покрытые) в итоговую статистику
523:         out.covered += covered;
524:         out.valid += valid;
525:     }
526:     return out;
527: }
