529: // форматированный вывод статистики для всего проекта
530: std::string format_summary(const Summary& s) {
531:     // ширина этого столбца должна быть не меньше, чем строка "TOTAL", которая там точно будет
532:     std::size_t width = std::string_view("TOTAL").size();
533:     // в итоге выбираем width равный ширине самого широкого пути до файла
534:     for (const auto& f : s.files)
535:         width = std::max(width, f.path.size());
536: 
537:     // шапка и все записи по файлам. и итоговая запись с "всего" и "покрыто" по всему проекту
538:     std::string out = "coverage union (line-based, Cobertura)\n";
539:     for (const auto& f : s.files)
540:         out += format_line(f.path, f.covered, f.valid, width);
541:     out += format_line("TOTAL", s.covered, s.valid, width);
542: 
543:     // если есть непокрытые строки, вывод их с подробностями
544:     if (!s.uncovered.empty()) {
545:         out += "\nuncovered lines:\n";
546:         for (const auto& u : s.uncovered) {
547:             out += "  ";
548:             out += u.path;
549:             out += ": ";
550:             for (std::size_t i = 0; i < u.lines.size(); ++i) {
551:                 if (i != 0)
552:                     out += ", ";
553:                 out += std::to_string(u.lines[i]);
554:             }
555:             out += '\n';
556:         }
557:     }
558:     return out;
559: }
560: // ================================================================================================
561: // если есть файлы, которые должны были быть инструментированы, но не были, - вернуть их список
562: // expected - список путей из манифеста
563: // fold_case должен быть тот же, что и переданный в parse_cobertura
564: std::vector<std::string> missing_expected(const Coverage& cov, std::span<const std::string> expected, bool fold_case) {
565:     std::vector<std::string> missing;
566:     for (const auto& e : expected) {
567:         const auto it = cov.files.find(normalize_key(e, fold_case));
568:         // если файла нет или у него ноль инструментированных строк
569:         if (it == cov.files.end() || it->second.hits.empty())
570:             missing.push_back(e);
571:     }
572:     return missing;
573: }
