 33: // '>' внутри кавычек не считается концом тега
 34: std::size_t find_tag_end(std::string_view s, std::size_t start) {
 35:     char quote = '\0';
 36:     for (std::size_t i = start; i < s.size(); ++i) {
 37:         const char c = s[i];
 38:         // quote == '\0' -> мы вне кавычек
 39:         // quote != '\0' -> мы в кавычках
 40:         if (quote != '\0') {
 41:             // если при этом текущий символ - также кавычка, то она закрывающая. выходим из кавычек
 42:             if (c == quote)
 43:                 quote = '\0';
 44:         }
 45:         // quote == '\0'. если сейчас кавычка, мы в неё зашли. запоминаем это в quote
 46:         else if (c == '"' || c == '\'') {
 47:             quote = c;
 48:         }
 49:         // quote == '\0', > реально закрывает тэг
 50:         else if (c == '>') {
 51:             return i;
 52:         }
 53:     }
 54:     return std::string_view::npos;
 55: }
