 57: struct Tag {
 58:     std::string_view name{};   // "class", "line", "package", ...
 59:     std::string_view text{};   // "<class ...>", "</class>", "<line ... />"
 60:     std::size_t begin = 0;     // индекс '<'
 61:     std::size_t end = 0;       // индекс '>'
 62:     bool closing = false;      // </...>
 63:     bool self_closing = false; // .../>
 64: };
 65: 
 66: // обособленный поиск тега - не считаем комментарии и строки, которые xml-парсер игнорирует
 67: class TagReader {
 68: public:
 69:     explicit TagReader(std::string_view xml) : xml_(xml) {}
 70: 
 71:     // true  - тег прочитан
 72:     // false - конец документа
 73:     // unexpected - malformed
 74:     std::expected<bool, ParseError> next(Tag& out);
 75: 
 76: private:
 77:     std::string_view xml_;
 78:     std::size_t pos_ = 0;
 79: };
 80: 
 81: // поиск следующего тега, пропуск комментариев и деклараций. падение на CDATA, DOCTYPE -
 82: // не поддерживаем этот синтаксис. 1) там внутри мб < или > 2) .cobertira.xml не имеет такого синтаксиса
 83: // next() не проверяет, есть ли у того же <class> закрывающий </class>. парный закрывающий ищет автомат парсера
 84: std::expected<bool, ParseError> TagReader::next(Tag& out) {
 85:     while (pos_ < xml_.size()) {
 86:         std::size_t tag_open_angle = xml_.find("<", pos_);
 87:         // если начала открывающего тега больше нет, теги закончились - это конец документа
 88:         if (tag_open_angle == std::string_view::npos)
 89:             return false;
 90:         // сдвигаемся на <
 91:         pos_ = tag_open_angle;
 92: 
 93:         // что именно находится за < ? comment/declaration -> пропускаем
 94:         if (xml_.substr(pos_, 4) == "<!--") {
 95:             // ищем закрытие комментария. если его нет - "плохой формат"
 96:             const auto comment_end = xml_.find("-->", pos_ + std::string_view("<!--").size());
 97:             if (comment_end == std::string_view::npos)
 98:                 return std::unexpected(make_error(ParseReason::malformed, pos_, "unterminated comment"));
 99:             // если закрывающая часть есть, передвигаемся за неё
100:             pos_ = comment_end + std::string_view("-->").size();
101:             continue;
102:         }
103: 
104:         if (xml_.substr(pos_, 2) == "<?") {
105:             // ищем закрытие декларации. если его нет - "плохой формат"
106:             const auto declaration_end = xml_.find("?>", pos_ + std::string_view("<?").size());
107:             if (declaration_end == std::string_view::npos)
108:                 return std::unexpected(make_error(ParseReason::malformed, pos_, "unterminated declaration"));
109:             // если закрывающая часть есть, передвигаемся за неё
110:             pos_ = declaration_end + std::string_view("?>").size();
111:             continue;
112:         }
113:         // если <!DOCTYPE.../<![CDATA... - падаем. т.к. не поддерживаем
114:         if (xml_.substr(pos_, 2) == "<!")
115:             return std::unexpected(make_error(ParseReason::malformed, pos_, "unsupported markup"));
116: 
117:         // найти конец тега
118:         const auto tag_end = find_tag_end(xml_, pos_);
119:         if (tag_end == std::string_view::npos)
120:             return std::unexpected(make_error(ParseReason::malformed, pos_, "unterminated tag"));
121: 
122:         // если дошли до сюда, то тег "нормальный", надо найти его имя и запомнить в out
123:         out.begin = pos_;
124:         out.end = tag_end;
125:         out.text = xml_.substr(pos_, tag_end - pos_ + 1);
126:         out.self_closing = xml_[tag_end - 1] == '/';
127: 
128:         // нахождение имени тега
129:         std::size_t name_start = pos_ + 1;
130:         // это закрывающий тег?
131:         bool closing = false;
132:         if (name_start < tag_end && xml_[name_start] == '/') {
133:             // да, закрывающий. и для нахождения имени сдвигаемся ещё на один
134:             closing = true;
135:             ++name_start;
136:         }
137:         out.closing = closing;
138: 
139:         // идём от начала имени по одному символу, пока это не терминатор (space-symbol, >, etc.)
140:         std::size_t name_end = name_start;
141:         while (name_end < tag_end && is_name_char(xml_[name_end]))
142:             ++name_end;
143: 
144:         // <> или < class>
145:         if (name_end == name_start)
146:             return std::unexpected(make_error(ParseReason::malformed, pos_, "missing tag name or wrong name format"));
147: 
148:         // проверка что не </tag/> и не </tag attr="x">
149:         if (closing) {
150:             for (std::size_t i = name_end; i < tag_end; ++i) {
151:                 if (!is_xml_space(xml_[i]))
152:                     return std::unexpected(
153:                         make_error(ParseReason::malformed, pos_, "unexpected characters in closing tag"));
154:             }
155:         }
156: 
157:         // на что заканчивается имя тега
158:         const char delim = (name_end < tag_end) ? xml_[name_end] : '>';
159:         // если имя заканчивается не на пробельный символ, не на / и не на > то это "плохой формат"
160:         if (!(is_xml_space(delim) || delim == '/' || delim == '>'))
161:             return std::unexpected(make_error(ParseReason::malformed, pos_, "improper end of tag name"));
162: 
163:         out.name = xml_.substr(name_start, name_end - name_start);
164: 
165:         // тег валидный, прыгаем за него и выходим из цикла - т.к. next tag найден, его out заполнен
166:         pos_ = tag_end + 1;
167:         return true;
168:     }
169:     return false;
170: }
171: 
172: // "самостоятельный" ли тег?
173: // <class ...>, <line ...> - да; <classes>/<lines> не должны совпасть
174: bool tag_starts(std::string_view s, std::size_t p, std::string_view name) {
175:     if (p + name.size() > s.size() || s.substr(p, name.size()) != name)
176:         return false;
177:     if (p + name.size() == s.size())
178:         return true;
179:     const char n = s[p + name.size()];
180:     return is_xml_space(n) || n == '>' || n == '/';
181: }
182: 
183: // порядок атрибутов не важен; кавычки одинарные/двойные
184: // optional - value that may or may not be present
185: std::optional<std::string_view> find_attr(std::string_view tag, std::string_view name) {
186:     std::size_t i = 0;
187:     while (i < tag.size()) {
188:         while (i < tag.size() && is_xml_space(tag[i]))
189:             ++i;
190:         if (i >= tag.size() || tag[i] == '>' || tag[i] == '/')
191:             break;
192: 
193:         const std::size_t ns = i;
194:         while (i < tag.size() && !is_xml_space(tag[i]) && tag[i] != '=' && tag[i] != '>' && tag[i] != '/')
195:             ++i;
196:         const std::string_view aname = tag.substr(ns, i - ns);
197: 
198:         while (i < tag.size() && is_xml_space(tag[i]))
199:             ++i;
200:         if (i >= tag.size() || tag[i] != '=')
201:             continue;
202:         ++i;
203:         while (i < tag.size() && is_xml_space(tag[i]))
204:             ++i;
205:         if (i >= tag.size() || (tag[i] != '"' && tag[i] != '\''))
206:             return std::nullopt;
207: 
208:         const char quote = tag[i++];
209:         const std::size_t vs = i;
210:         while (i < tag.size() && tag[i] != quote)
211:             ++i;
212:         if (i >= tag.size())
213:             return std::nullopt;
214: 
215:         const std::string_view value = tag.substr(vs, i - vs);
216:         ++i;
217:         if (aname == name)
218:             return value;
219:     }
220:     return std::nullopt;
221: }
222: 
223: std::string decode_entities(std::string_view raw) {
224:     std::string out;
225:     out.reserve(raw.size());
226:     // в xml спецсимволы лежат как &имя; (& будет &amp; < &lt; и т.д.)
227:     // чтобы это не испортило пути, спецсимв. -> обычные символы
228:     for (std::size_t i = 0; i < raw.size(); ++i) {
229:         if (raw[i] != '&') {
230:             out += raw[i];
231:         } else if (raw.substr(i, 5) == "&amp;") {
232:             out += '&';
233:             i += 4;
234:         } else if (raw.substr(i, 4) == "&lt;") {
235:             out += '<';
236:             i += 3;
237:         } else if (raw.substr(i, 4) == "&gt;") {
238:             out += '>';
239:             i += 3;
240:         } else if (raw.substr(i, 6) == "&quot;") {
241:             out += '"';
242:             i += 5;
243:         } else if (raw.substr(i, 6) == "&apos;") {
244:             out += '\'';
245:             i += 5;
246:         } else {
247:             out += raw[i];
248:         }
249:     }
250:     return out;
251: }
252: 
253: bool parse_u64(std::string_view s, std::uint64_t& out) {
254:     if (s.empty())
255:         return false;
256:     const auto [ptr, ec] = std::from_chars(s.data(), s.data() + s.size(), out);
257:     return ec == std::errc{} && ptr == s.data() + s.size();
258: }
259: 
260: // \ -> /, схлопнуть //, на Windows lower-case
261: std::string normalize_key(std::string_view path, bool fold_case) {
262:     std::string out;
263:     out.reserve(path.size());
264:     bool prev_slash = false;
265:     for (char c : path) {
266:         if (c == '\\')
267:             c = '/';
268:         if (c == '/' && prev_slash)
269:             continue;
270:         prev_slash = (c == '/');
271:         if (fold_case && c >= 'A' && c <= 'Z')
272:             c = static_cast<char>(c - 'A' + 'a');
273:         out += c;
274:     }
275:     return out;
276: }
277: 
278: std::string relative_path(std::string_view path, std::string_view source_root) {
279:     if (source_root.empty())
280:         return std::string(path);
281:     const std::filesystem::path p{path};
282:     const std::filesystem::path root{source_root};
283:     const std::string rel = p.lexically_relative(root).generic_string();
284:     if (rel.empty() || rel.starts_with(".."))
285:         return std::string(path);
286:     return rel;
287: }
288: 
289: // форматный вывод статистики для отдельного файла
290: std::string format_line(std::string_view path, int covered, int valid, std::size_t width) {
291:     const double pct = valid == 0 ? 0.0 : 100.0 * static_cast<double>(covered) / static_cast<double>(valid);
292:     return std::format("{:<{}} {:>5}/{:<5} {:>7.2f}%\n", path, width, covered, valid, pct);
293: }
