 59:     // контракт - Tag::text это весь тег, включая <...>
 60:     std::string_view text{};   // "<class ...>", "</class>", "<line ... />"
 61:     std::size_t begin = 0;     // индекс '<'
 62:     bool closing = false;      // </...>
 63:     bool self_closing = false; // .../>
