 73: class TagReader {
 74: public:
 75:     explicit TagReader(std::string_view xml) : xml_(xml) {}
 76: 
 77:     // true  - тег прочитан
 78:     // false - конец документа
 79:     // unexpected - malformed
 80:     std::expected<bool, ParseError> next(Tag& out);
