 90: std::expected<bool, ParseError> TagReader::next(Tag& out) {
 91:     while (pos_ < xml_.size()) {
 92:         std::size_t tag_open_angle = xml_.find("<", pos_);
 93:         // если начала открывающего тега больше нет, теги закончились - это конец документа
 94:         if (tag_open_angle == std::string_view::npos)
 95:             return false;
 96:         // сдвигаемся на <
 97:         pos_ = tag_open_angle;
 98: 
 99:         // что именно находится за < ? comment/declaration -> пропускаем
100:         if (xml_.substr(pos_, 4) == "<!--") {
101:             // ищем закрытие комментария. если его нет - "плохой формат"
102:             const auto comment_end = xml_.find("-->", pos_ + std::string_view("<!--").size());
103:             if (comment_end == std::string_view::npos)
104:                 return std::unexpected(make_error(ParseReason::malformed, pos_, "unterminated comment"));
105:             // если закрывающая часть есть, передвигаемся за неё
106:             pos_ = comment_end + std::string_view("-->").size();
107:             continue;
108:         }
109: 
110:         if (xml_.substr(pos_, 2) == "<?") {
111:             // ищем закрытие декларации. если его нет - "плохой формат"
112:             const auto declaration_end = xml_.find("?>", pos_ + std::string_view("<?").size());
113:             if (declaration_end == std::string_view::npos)
114:                 return std::unexpected(make_error(ParseReason::malformed, pos_, "unterminated declaration"));
115:             // если закрывающая часть есть, передвигаемся за неё
116:             pos_ = declaration_end + std::string_view("?>").size();
117:             continue;
118:         }
119:         // если <!DOCTYPE.../<![CDATA... - падаем. т.к. не поддерживаем
120:         if (xml_.substr(pos_, 2) == "<!")
121:             return std::unexpected(make_error(ParseReason::malformed, pos_, "unsupported markup"));
122: 
123:         // найти конец тега
124:         const auto tag_end = find_tag_end(xml_, pos_);
125:         if (tag_end == std::string_view::npos)
126:             return std::unexpected(make_error(ParseReason::malformed, pos_, "unterminated tag"));
127: 
128:         // если дошли до сюда, то тег "нормальный", надо найти его имя и запомнить в out
129:         out.begin = pos_;
130:         out.text = xml_.substr(pos_, tag_end - pos_ + 1);
131:         out.self_closing = xml_[tag_end - 1] == '/';
132: 
133:         // нахождение имени тега
134:         std::size_t name_start = pos_ + 1;
135:         // это закрывающий тег?
136:         bool closing = false;
137:         if (name_start < tag_end && xml_[name_start] == '/') {
138:             // да, закрывающий. и для нахождения имени сдвигаемся ещё на один
139:             closing = true;
140:             ++name_start;
141:         }
142:         out.closing = closing;
143: 
144:         // идём от начала имени по одному символу, пока это не терминатор (space-symbol, >, etc.)
145:         std::size_t name_end = name_start;
146:         while (name_end < tag_end && is_name_char(xml_[name_end]))
147:             ++name_end;
148: 
149:         // <> или < class>
150:         if (name_end == name_start)
151:             return std::unexpected(make_error(ParseReason::malformed, pos_, "missing tag name or wrong name format"));
152: 
153:         // проверка что не </tag/> и не </tag attr="x">
154:         if (closing) {
155:             for (std::size_t i = name_end; i < tag_end; ++i) {
156:                 if (!is_xml_space(xml_[i]))
157:                     return std::unexpected(
158:                         make_error(ParseReason::malformed, pos_, "unexpected characters in closing tag"));
159:             }
160:         }
161: 
162:         // на что заканчивается имя тега
163:         const char delim = (name_end < tag_end) ? xml_[name_end] : '>';
164:         // если имя заканчивается не на пробельный символ, не на / и не на > то это "плохой формат"
165:         if (!(is_xml_space(delim) || delim == '/' || delim == '>'))
166:             return std::unexpected(make_error(ParseReason::malformed, pos_, "improper end of tag name"));
167: 
168:         out.name = xml_.substr(name_start, name_end - name_start);
169: 
170:         // тег валидный, прыгаем за него и выходим из цикла - т.к. next tag найден, его out заполнен
171:         pos_ = tag_end + 1;
172:         return true;
173:     }
174:     return false;
175: }
