180: std::optional<std::string_view> find_attr(std::string_view attributes, std::string_view name) {
181:     std::size_t i = 0;
182:     while (i < attributes.size()) {
183:         while (i < attributes.size() && is_xml_space(attributes[i]))
184:             ++i;
185:         if (i >= attributes.size() || attributes[i] == '>' || attributes[i] == '/')
186:             break;
187: 
188:         const std::size_t ns = i;
189:         while (i < attributes.size() && !is_xml_space(attributes[i]) && attributes[i] != '=' && attributes[i] != '>' &&
190:                attributes[i] != '/')
191:             ++i;
192:         const std::string_view aname = attributes.substr(ns, i - ns);
193: 
194:         while (i < attributes.size() && is_xml_space(attributes[i]))
195:             ++i;
196:         if (i >= attributes.size() || attributes[i] != '=')
197:             continue;
198:         ++i;
199:         while (i < attributes.size() && is_xml_space(attributes[i]))
200:             ++i;
201:         if (i >= attributes.size() || (attributes[i] != '"' && attributes[i] != '\''))
202:             return std::nullopt;
203: 
204:         const char quote = attributes[i++];
205:         const std::size_t vs = i;
206:         while (i < attributes.size() && attributes[i] != quote)
207:             ++i;
208:         if (i >= attributes.size())
209:             return std::nullopt;
210: 
211:         const std::string_view value = attributes.substr(vs, i - vs);
212:         ++i;
213:         if (aname == name)
214:             return value;
215:     }
216:     return std::nullopt;
