219: std::string decode_entities(std::string_view raw) {
220:     std::string out;
221:     out.reserve(raw.size());
222:     // в xml спецсимволы лежат как &имя; (& будет &amp; < &lt; и т.д.)
223:     // чтобы это не испортило пути, спецсимв. -> обычные символы
224:     for (std::size_t i = 0; i < raw.size(); ++i) {
225:         if (raw[i] != '&') {
226:             out += raw[i];
227:         } else if (raw.substr(i, 5) == "&amp;") {
228:             out += '&';
229:             i += 4;
230:         } else if (raw.substr(i, 4) == "&lt;") {
231:             out += '<';
232:             i += 3;
233:         } else if (raw.substr(i, 4) == "&gt;") {
234:             out += '>';
235:             i += 3;
236:         } else if (raw.substr(i, 6) == "&quot;") {
237:             out += '"';
238:             i += 5;
239:         } else if (raw.substr(i, 6) == "&apos;") {
240:             out += '\'';
241:             i += 5;
242:         } else {
243:             out += raw[i];
244:         }
245:     }
246:     return out;
247: }
