293: // parse_cobertura - проход по сырому cobertura.xml
294: std::expected<Coverage, ParseError> parse_cobertura(std::string_view xml, bool fold_case) {
295:     Coverage cov;
296:     // string_view одной строкой всего .cobertura.xml
297:     TagReader reader(xml);
298:     // текущий тег, текущий класс, к-во классов и строк вообще для итог.отчёта
299:     Tag tag{};
300:     // если мы не внутри класса, current==nullptr
301:     FileCoverage* current = nullptr;
302:     std::size_t classes = 0;
303:     std::size_t lines = 0;
304: 
305:     while (true) {
306:         // следующий тег
307:         auto has = reader.next(tag);
308:         // if has -> std::expected вернул bool, парс тега случился
309:         // if !has -> std::expected вернул ParseError из std::expected<bool, ParseError>.
310:         // имеем ParseError
311:         if (!has)
312:             return std::unexpected(has.error());
313:         // тут точно has и bool==false -> документ закончился, парсить больше нечего, выходим
314:         if (!*has)
315:             break;
316: 
317:         // к этому моменту has==true && *has==true
318:         // сейчас тег class и он не-закрывающий - <class>
319:         if (tag.name == "class" && !tag.closing) {
320:             // если current не null, то мы внутри класса. и встретили открывающий <class>
321:             // у cobertura влож.классов быть не должно -> ошибка
322:             if (current != nullptr)
323:                 return std::unexpected(make_error(ParseReason::malformed, tag.begin, "nested <class>"));
324: 
325:             // иначе - мы не внутри класса, а внутри тега <class ...>
326:             // ищем тег после <class (т.е. сам class не учитываем, т.к. его и не нужно учитывать)
327:             auto raw = find_attr(tag.attributes(), "filename");
328:             // там обязательно должен быть filename, если нет - "плохой формат"
329:             if (!raw)
330:                 return std::unexpected(make_error(ParseReason::malformed, tag.begin, "no filename"));
331: 
332:             // переделать спец.символы в обычные и в key, проверить что path непуст, сделать регистр соотв. ОС
333:             const std::string path = decode_entities(*raw);
334:             // filename из пробельных не считаем пустым. ии советует не trim, чтобы не протить реальные пробелы в именах
335:             if (path.empty())
336:                 return std::unexpected(make_error(ParseReason::malformed, tag.begin, "empty filename"));
337:             const std::string key = normalize_key(path, fold_case);
338:             // добавление FileCoverage в общий Coverage. если для данного path пусто, то будет
339:             // создана новая запись и добавлен путь до файла. если же path существует, то его hits увеличатся
340:             FileCoverage& fc = cov.files[key];
341:             if (fc.display_path.empty())
342:                 fc.display_path = path;
343: 
344:             ++classes;
345:             // если не <class/> a <class>, то мы внутри класса и надо будет проверить сущ-вование </class>
346:             if (!tag.self_closing)
347:                 current = &fc;
348:         } else if (tag.name == "class" && tag.closing) {
349:             // встретили </class>. если мы не внутри <class>, то </class> ни к чему не относится
350:             if (current == nullptr)
351:                 return std::unexpected(make_error(ParseReason::malformed, tag.begin, "unexpected </class>"));
352:             // иначе мы были внутри класса и он закрылся
353:             current = nullptr;
354:         } else if (tag.name == "line" && !tag.closing) {
355:             // line не относящийся ни к какому классу -> "плохой формат"
356:             if (current == nullptr)
357:                 return std::unexpected(make_error(ParseReason::malformed, tag.begin, "<line> outside <class>"));
358: 
359:             // теги внутри line, если нет - "плохой формат"
360:             const std::string_view attrs = tag.attributes();
361:             auto raw_n = find_attr(attrs, "number");
362:             auto raw_h = find_attr(attrs, "hits");
363:             if (!raw_n || !raw_h)
364:                 return std::unexpected(make_error(ParseReason::malformed, tag.begin, "line without number/hits"));
365: 
366:             // парс number/hits, если не удалось или n не в пределах нормы - "плохой формат"
367:             // hits в рамках xml - беззнаковый, а значит шире. number/hits сначала парс.в такой тип
368:             std::uint64_t n = 0, h = 0;
369:             if (!parse_u64(*raw_n, n) || !parse_u64(*raw_h, h))
370:                 return std::unexpected(make_error(ParseReason::malformed, tag.begin, "bad number/hits"));
371:             // считаем, что в исходнике к-во строк не превышает INT_MAX
372:             if (n == 0 || n > static_cast<std::uint64_t>(std::numeric_limits<int>::max()))
373:                 return std::unexpected(make_error(ParseReason::malformed, tag.begin,
374:                                                   "line number is out of supported range [1; INT_MAX]"));
375:             // текущая строка и нахождение максимальных hits для неё
376:             const int line_no = static_cast<int>(n);
377:             // -> означает разыменов.указателя и взять соотв.поле (то же, что и (*current).hits[line_no])
378:             // current->hits[line_no] - обращение к std::map<int, uint64_t> - мапа из номер_строки и max_hits
379:             // max_hits = max(max_hits, current_hits)
380:             // если строки ещё не было, то hits[line_no] вставляет её с hits=0 и возвр. ссылку на неё
381:             auto slot = current->hits[line_no];
382:             slot = std::max(slot, h);
383:             ++lines;
384:         }
385:         // package/classes/methods/method/lines/source_file/... игнорируем
386:     }
387:     // мы не на <class> и не на </class> или <class/>, но как бы "внутри класса"? незакрытый класс
388:     if (current != nullptr)
389:         return std::unexpected(make_error(ParseReason::malformed, 0, "unclosed <class>"));
390:     // если в отчёте не было классов / строк - не должно так быть, ошибка
391:     if (classes == 0)
392:         return std::unexpected(make_error(ParseReason::no_classes, 0, "no <class> in report"));
393:     if (lines == 0)
394:         return std::unexpected(make_error(ParseReason::no_lines, 0, "no <line> in report"));
395:     return cov;
396: }
