399: // итоговая статистика по проекту
400: Summary summarize(const Coverage& cov, std::string_view source_root) {
401:     Summary out{};
402:     for (const auto& entry : cov.files) {
403:         const auto& fc = entry.second;
404:         // относит. путь, подсчёт - покрытые и какие именно непокрытые
405:         const std::string display = relative_path(fc.display_path, source_root);
406:         int covered = 0;
407:         std::vector<int> missing;
408:         for (const auto& [line, h] : fc.hits) {
409:             if (h > 0)
410:                 ++covered;
411:             else
412:                 missing.push_back(line);
413:         }
414:         // сколько всего инструментированных строк по данному файлу
415:         const int valid = static_cast<int>(fc.hits.size());
416:         // добавляем в итоговый Summary статистику по текущему файлу
417:         out.files.push_back(FileStat{display, covered, valid});
418:         // есть непокрытые строки? в uncovered curr-файла перемещаем missing, тк сам missing здесь более не нужен
419:         if (!missing.empty())
420:             out.uncovered.push_back(Uncovered{display, std::move(missing)});
421:         // вклад данного файла (всего и покрытые) в итоговую статистику
422:         out.covered += covered;
423:         out.valid += valid;
424:     }
425:     return out;
426: }
